theorem log_sum_product_eq_21000 : 
    let n := 20
    let m := 100
    let a (k : ℕ) : ℝ := Real.log (3^(k^2)) / Real.log (5^k)
    let b (k : ℕ) : ℝ := Real.log (25^k) / Real.log (9^k)
    let S := (∑ k in Finset.Icc 1 n, a k) * (∑ k in Finset.Icc 1 m, b k)
    in S = 21000 := sorry

theorem roots_of_cubic_cos : 
    let P (x : ℝ) := x^3 + a * x^2 + b * x + c
    let r1 := Real.cos (2 * π / 7)
    let r2 := Real.cos (4 * π / 7)
    let r3 := Real.cos (6 * π / 7)
    in (∀ x, P x = (x - r1) * (x - r2) * (x - r3)) → a * b * c = 1/32 := sorry

theorem greatest_distance_between_sets :
    let A : Set ℂ := {z | z ^ 3 - 8 = 0}
    let B : Set ℂ := {z | z ^ 3 - 8 * z ^ 2 - 8 * z + 64 = 0}
    in sSup {d | ∃ a ∈ A, ∃ b ∈ B, d = Complex.dist a b} = 2 * Real.sqrt 21 := sorry
